{
  "$id": "https://edopsys.local/schemas/clp001/evidence-artifact.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {
        "properties": {
          "verification_status": {
            "const": "VERIFIED"
          }
        }
      },
      "then": {
        "required": [
          "verified_by",
          "verified_at"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "evidence_class": {
            "const": "E1"
          }
        }
      },
      "then": {
        "properties": {
          "parent_evidence_ids": {
            "minItems": 1
          }
        }
      }
    }
  ],
  "properties": {
    "authority_source_ids": {
      "items": {
        "maxLength": 256,
        "minLength": 1,
        "type": "string"
      },
      "type": "array",
      "uniqueItems": true
    },
    "captured_by": {
      "maxLength": 256,
      "minLength": 1,
      "type": "string"
    },
    "content_hash": {
      "pattern": "^sha256:[0-9a-f]{64}$",
      "type": "string"
    },
    "created_at": {
      "format": "date-time",
      "type": "string"
    },
    "evidence_class": {
      "enum": [
        "E0",
        "E1",
        "E2",
        "E3",
        "E4",
        "E5",
        "E6",
        "E7"
      ],
      "type": "string"
    },
    "evidence_id": {
      "pattern": "^ev_[A-Za-z0-9._:-]+$",
      "type": "string"
    },
    "evidence_type": {
      "maxLength": 128,
      "minLength": 1,
      "type": "string"
    },
    "parent_evidence_ids": {
      "items": {
        "pattern": "^ev_[A-Za-z0-9._:-]+$",
        "type": "string"
      },
      "type": "array",
      "uniqueItems": true
    },
    "policy_ids": {
      "items": {
        "maxLength": 256,
        "minLength": 1,
        "type": "string"
      },
      "type": "array",
      "uniqueItems": true
    },
    "privacy_class": {
      "enum": [
        "PUBLIC",
        "INTERNAL",
        "RESIDENT_PRIVATE",
        "WORKER_PRIVATE",
        "RESTRICTED"
      ],
      "type": "string"
    },
    "related_event_ids": {
      "items": {
        "pattern": "^evt_[A-Za-z0-9._:-]+$",
        "type": "string"
      },
      "type": "array",
      "uniqueItems": true
    },
    "retention_class": {
      "enum": [
        "CASE_LIFECYCLE",
        "AUDIT_LONG_TERM",
        "LEGAL_HOLD",
        "PORTABLE_WORKGRAPH"
      ],
      "type": "string"
    },
    "schema_version": {
      "const": "1.0.0"
    },
    "source": {
      "maxLength": 512,
      "minLength": 1,
      "type": "string"
    },
    "storage_ref": {
      "maxLength": 2048,
      "minLength": 1,
      "type": "string"
    },
    "subject": {
      "maxLength": 512,
      "minLength": 1,
      "type": "string"
    },
    "verification_status": {
      "enum": [
        "UNVERIFIED",
        "VERIFIED",
        "REJECTED",
        "SUPERSEDED"
      ],
      "type": "string"
    },
    "verified_at": {
      "format": "date-time",
      "type": [
        "string",
        "null"
      ]
    },
    "verified_by": {
      "maxLength": 256,
      "type": [
        "string",
        "null"
      ]
    }
  },
  "required": [
    "schema_version",
    "evidence_id",
    "evidence_class",
    "evidence_type",
    "created_at",
    "captured_by",
    "subject",
    "source",
    "storage_ref",
    "content_hash",
    "parent_evidence_ids",
    "related_event_ids",
    "authority_source_ids",
    "policy_ids",
    "verification_status",
    "retention_class",
    "privacy_class"
  ],
  "title": "CLP-001 EvidenceArtifact",
  "type": "object"
}

{
  "$id": "https://edopsys.local/schemas/clp001/worker-fixture.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "capabilities": {
      "additionalProperties": false,
      "properties": {
        "basic_plumbing_maintenance": {
          "enum": [
            "VERIFIED",
            "NOT_VERIFIED",
            "EXPIRED"
          ],
          "type": "string"
        }
      },
      "required": [
        "basic_plumbing_maintenance"
      ],
      "type": "object"
    },
    "credentials_current": {
      "type": "boolean"
    },
    "disciplinary_block": {
      "enum": [
        "NONE",
        "ACTIVE"
      ],
      "type": "string"
    },
    "employment_authorization": {
      "enum": [
        "ACTIVE",
        "INACTIVE",
        "EXPIRED"
      ],
      "type": "string"
    },
    "expected_decision": {
      "enum": [
        "ELIGIBLE",
        "INELIGIBLE_CAPABILITY",
        "INELIGIBLE_AUTHORIZATION"
      ],
      "type": "string"
    },
    "maintenance_role": {
      "enum": [
        "ACTIVE",
        "INACTIVE"
      ],
      "type": "string"
    },
    "property_authorization": {
      "enum": [
        "ACTIVE",
        "INACTIVE",
        "EXPIRED"
      ],
      "type": "string"
    },
    "supervision_present": {
      "type": "boolean"
    },
    "supervision_required": {
      "type": "boolean"
    },
    "trainings": {
      "additionalProperties": false,
      "properties": {
        "fixture_repair_training": {
          "enum": [
            "CURRENT",
            "NOT_VERIFIED",
            "EXPIRED"
          ],
          "type": "string"
        }
      },
      "required": [
        "fixture_repair_training"
      ],
      "type": "object"
    },
    "worker_id": {
      "enum": [
        "WORKER-A",
        "WORKER-B",
        "WORKER-C"
      ],
      "type": "string"
    }
  },
  "required": [
    "worker_id",
    "employment_authorization",
    "property_authorization",
    "maintenance_role",
    "capabilities",
    "trainings",
    "credentials_current",
    "disciplinary_block",
    "supervision_required",
    "supervision_present",
    "expected_decision"
  ],
  "title": "CLP-001 Worker Eligibility Fixture",
  "type": "object"
}
